import {escapeHTML as e} from './core.js?v=20261014e';
export function accountPage(space){const i=space.info(),appURL=(typeof location!=='undefined'&&location.origin&&location.pathname)?location.origin+location.pathname:'https://poundpop35-creator.github.io/RU-Study-Planner/';return `<div class="page-heading"><div><div class="eyebrow">YOUR ONLINE STUDY SPACE</div><h1>ห้องเรียนออนไลน์ของฉัน</h1><p>โน้ต รูปภาพ แผนการเรียน และผลฝึกสอบ เก็บใน Supabase เปิดต่อได้จากทุกเครื่องด้วยบัญชีเดียวกัน</p></div></div><section class="panel account-panel"><div class="notebook-status"><span class="status-dot"></span><strong data-sync-status>${e(i.status)}</strong></div>${i.user?`<h2>${e(i.user.email||'บัญชีของฉัน')}</h2><p>แอปบันทึกทุกการแก้ไขใน Supabase อัตโนมัติ เปลี่ยนเครื่องได้เมื่อขึ้น “บันทึกใน Supabase แล้ว” หากเน็ตหลุด ระบบจะพักงานไว้ชั่วคราวและส่งต่อเมื่อเชื่อมต่อได้</p><p>ซิงก์ล่าสุด: <span id="last-sync">${i.lastSync?e(new Date(i.lastSync).toLocaleString('th-TH')):'ยังไม่มี'}</span></p><div class="button-row"><button class="button primary" data-action="account-sync">ซิงก์ตอนนี้</button><button class="button secondary" data-action="account-signout">ออกจากระบบ</button></div><div id="sync-conflict" ${i.conflict?'':'hidden'} class="notice danger"><h3>มีข้อมูลใหม่จากอีกเครื่อง</h3><p>เลือกฉบับที่จะใช้ ระบบจะเก็บทั้งสองฉบับไว้ในเครื่องก่อนแทนที่</p><div class="button-row"><button class="button secondary" data-action="account-remote">ใช้ฉบับคลาวด์</button><button class="button secondary" data-action="account-local">ใช้ฉบับเครื่องนี้</button></div></div><hr><h3>เริ่มใช้ข้อมูลเดิมของเครื่องนี้</h3><p>ถ้าเคยเรียนหรือจดก่อนเข้าสู่ระบบ ให้คัดลอกข้อมูลชุดนั้นเข้าบัญชีนี้หนึ่งครั้ง</p><button class="button secondary" data-action="account-import-guest">คัดลอกข้อมูลก่อนเข้าสู่ระบบ</button>`:`<h2>เข้าสู่บัญชีเดียว เรียนต่อได้ทุกเครื่อง</h2><p>ลงชื่อเข้าใช้ก่อนเริ่มเรียนและจดโน้ต เพื่อให้ทุกอย่างอยู่ในบัญชีออนไลน์ของคุณ</p><button class="button primary google-signin" id="google-signin" data-action="account-google" ${i.providers.google?'':'disabled'}>เข้าสู่ระบบด้วย Google</button><p id="google-setup-note" class="quiet-note" ${i.providers.google?'hidden':''}>โปรเจ็กต์นี้ยังไม่ได้เปิด Google Login ตั้งค่าตามขั้นตอนด้านล่างก่อน ปุ่มจะพร้อมใช้เมื่อโหลดหน้าใหม่</p><details><summary>ใช้อีเมลและรหัสผ่าน</summary><div class="account-fields"><label class="field">อีเมล<input id="account-email" type="email" autocomplete="email" placeholder="you@example.com"></label><label class="field">รหัสผ่าน<input id="account-password" type="password" minlength="8" autocomplete="current-password" placeholder="อย่างน้อย 8 ตัวอักษร"></label><div class="button-row"><button class="button primary" data-action="account-signin">เข้าสู่ระบบ</button><button class="button secondary" data-action="account-signup">สร้างบัญชีเรียนใหม่</button></div><p class="quiet-note">บัญชีเรียนเป็นคนละบัญชีกับหน้า Dashboard ของ Supabase ต้องยืนยันอีเมลเมื่อสร้างบัญชีใหม่ และผู้ดูแลต้องตั้งค่า URL / ระบบส่งอีเมลก่อน</p></div></details>`}<button class="button secondary" data-action="account-reload">ตรวจการเชื่อมต่ออีกครั้ง</button><p id="account-message" role="status" class="account-message"></p></section><details class="panel auth-setup"><summary>ตั้งค่า Google Login ครั้งแรก (เจ้าของแอป)</summary><ol class="simple-list"><li>ใน <a target="_blank" rel="noopener noreferrer" href="https://supabase.com/dashboard/project/yikfrloyijdbwglswcww/auth/url-configuration">Authentication → URL Configuration ↗</a> ตั้ง Site URL และเพิ่ม Redirect URL เป็น <code>${e(appURL)}</code></li><li>ใน <a target="_blank" rel="noopener noreferrer" href="https://supabase.com/dashboard/project/yikfrloyijdbwglswcww/auth/providers">Sign In / Providers → Google ↗</a> เปิดใช้งาน และใส่ Client ID / Client Secret จาก Google Cloud โดยใช้ Callback URL <code>https://yikfrloyijdbwglswcww.supabase.co/auth/v1/callback</code></li><li>หากย้ายมา Vercel ให้ใส่ URL หน้าแอป Vercel ในรายการ Redirect ด้วย แล้วกลับมาโหลดแอปใหม่และกดเข้าสู่ระบบด้วย Google หากใช้วิธีอีเมล ให้ตั้ง SMTP ที่ส่งอีเมลยืนยันได้ด้วย</li></ol><p>ต้องเข้าสู่ระบบก่อนเริ่มบันทึกข้อมูลส่วนตัว ไม่มีโหมดจดที่เก็บเฉพาะเครื่อง ข้อมูลในเครื่องใช้เป็นสำเนาชั่วคราวป้องกันงานหายระหว่างเครือข่ายขัดข้องเท่านั้น</p></details>`;}
export async function accountAction(action,space,render,toast){
 const msg=document.getElementById('account-message');const say=t=>{if(msg)msg.textContent=t;};
 try{
  say('กำลังดำเนินการ…');
  if(action==='account-reload'){location.reload();return;}
  if(action==='account-google')await space.google();
  if(action==='account-signin'||action==='account-signup'){
   const email=document.getElementById('account-email').value.trim(),input=document.getElementById('account-password'),password=input.value;
   if(!email||!email.includes('@')||password.length<8)throw Error('กรอกอีเมลและรหัสผ่านอย่างน้อย 8 ตัวอักษร');
   if(action==='account-signin'){await space.signIn(email,password);input.value='';say('เข้าสู่ระบบแล้ว');}
   else{const active=await space.signUp(email,password);input.value='';say(active?'สร้างบัญชีแล้ว':'ตรวจอีเมลเพื่อยืนยันบัญชี แล้วกลับมาเข้าสู่ระบบ หากส่งอีเมลไม่ได้ต้องตั้ง SMTP ใน Supabase ก่อน');}
  }
  if(action==='account-sync'){await space.sync();say(space.info().status);}
  if(action==='account-signout'){await space.signOut();render();}
  if(action==='account-import-guest'&&confirm('แทนที่ข้อมูลบัญชีนี้ด้วยข้อมูลก่อนเข้าสู่ระบบ? ระบบเก็บสำเนาปัจจุบันในเครื่องให้ก่อน'))await space.importGuest();
  if(['account-remote','account-local'].includes(action)&&confirm('ยืนยันใช้ฉบับที่เลือก? อีกฉบับจะเก็บเป็นสำเนากู้คืนในเครื่อง')){await space.resolve(action==='account-local');render();}
 }catch(err){let text=err.message||'ดำเนินการไม่สำเร็จ';if(/Invalid login credentials/i.test(text))text='อีเมลหรือรหัสผ่านไม่ถูกต้อง หากยังไม่มีบัญชีเรียน ให้สร้างบัญชีก่อน';if(/Email not confirmed/i.test(text))text='กรุณายืนยันอีเมลก่อนเข้าสู่ระบบ';say(text);toast(text);}
}
